responseFormat.typescriptTypesReference:
type Citation = {
commentId: number;
};

type Clause = {
text: string;
citations: Citation[];
};

type Sentence = {
clauses: Clause[];
};

type Paragraph = {
id: string; // e.g. "tribe_who_they_are"
title: string;
sentences: Sentence[];
};

type Subtask = {
id: string;
title: string;
paragraphs: Paragraph[];
};

polisAnalysisPrompt.example:
{
"id": "tribe_insights",
"title": "Tribe Insights",
"paragraphs": [
{
"id": "tribe_who_they_are",
"title": "Who This Tribe Represents",
"sentences": [
{
"clauses": [
{
"text": "This tribe emphasizes pragmatic solutions and tends to weigh tradeoffs between impact and feasibility.",
"citations": [101, 115, 204]
},
{
"text": "Across their comments, they frame the issue around accountability and implementation details rather than broad principles.",
"citations": [132, 187]
}
]
}
]
},
{
"id": "tribe_internal_consensus",
"title": "Internal Consensus",
"sentences": [
{
"clauses": [
{
"text": "They show consistent agreement on the need for clear standards and transparent decision-making.",
"citations": [115, 190, 233]
}
]
}
]
},
{
"id": "tribe_distinctive_positions",
"title": "How They Differ From Other Tribes",
"sentences": [
{
"clauses": [
{
"text": "Compared with other tribes, they are more skeptical of symbolic measures and prioritize enforceable commitments.",
"citations": [204, 221]
}
]
}
]
},
{
"id": "tribe_voting_patterns",
"title": "Key Voting Patterns",
"sentences": [
{
"clauses": [
{
"text": "Their voting tends to cluster around statements that stress concrete outcomes, with less support for proposals framed primarily as aspirational.",
"citations": [101, 132, 233]
}
]
}
]
}
]
}
